local WANT = {
	["USER32.DLL"] = {"GetAsyncKeyState", "GetCursorPos", "SetCursorPos", "GetForegroundWindow", "GetClientRect",
		"ClientToScreen", "GetWindowThreadProcessId"},
	["KERNEL32.DLL"] = {"GetCurrentProcessId"},
	["DINPUT8.DLL"] = {"DirectInput8Create"},
